#!/usr/bin/env python3
"""Read-only PipeWire/Pulse OMNI-presence organ for the 777 voice arm.

This module does not own identity, memory, GRID, effects or acoustic authority.
It observes the existing local audio graph and projects one ephemeral fact:
whether the Firefox ChatGPT surface is acoustically occupied right now.

The canonical acoustic decision remains ``omega_arm_bus``.  This sensor is a
second, read-only discriminator that can only make local audio *more* cautious;
it can never grant an acoustic lease or effect authority.

Important evidence repair (2026-09-13): Firefox keeps ChatGPT sink-inputs
uncorked during a text-only turn.  Therefore stream existence/uncorked state is
NOT evidence that OMNI is speaking.  Playback is ACTIVE only when a bounded
``parec --monitor-stream=<index>`` probe observes actual PCM byte flow.  The
probe reads at most two bytes, persists nothing and discards those bytes
immediately.  A live ChatGPT capture stream remains strong evidence that the
OMNI Realtime surface owns the acoustic interaction.

UNKNOWN or stale sensor state deliberately fails closed for *local audio
emission*: losing the sensor is never interpreted as permission to speak.
"""
from __future__ import annotations

import dataclasses
import json
import os
import select
import subprocess
import threading
import time
from typing import Any, Callable, Iterable, Optional

SCHEMA = "OMEGA_777_OMNI_PRESENCE/v1"
STATE_ACTIVE = "ACTIVE"
STATE_INACTIVE = "INACTIVE"
STATE_UNKNOWN = "UNKNOWN"
RELEVANT_PULSE_OBJECTS = ("sink-input", "source-output")
DEFAULT_PLAYBACK_PROBE_S = 0.10
MAX_PLAYBACK_PROBES = 8


@dataclasses.dataclass(frozen=True)
class Match:
    direction: str
    index: int
    application_name: str
    process_binary: str
    media_name: str
    corked: bool

    def as_dict(self) -> dict[str, Any]:
        return dataclasses.asdict(self)


@dataclasses.dataclass(frozen=True)
class PresenceSnapshot:
    state: str
    observed_mono: float
    observed_wall: float
    reason: str
    matches: tuple[Match, ...] = ()

    @property
    def active(self) -> bool:
        return self.state == STATE_ACTIVE

    def as_dict(self) -> dict[str, Any]:
        return {
            "schema": SCHEMA,
            "state": self.state,
            "active": self.active,
            "observed_wall": self.observed_wall,
            "reason": self.reason,
            "matches": [m.as_dict() for m in self.matches],
            "effect_authority": False,
        }


def _bool_corked(value: Any) -> bool:
    if isinstance(value, bool):
        return value
    return str(value or "").strip().lower() in {"1", "true", "yes", "on"}


def _is_chatgpt_firefox(props: dict[str, Any]) -> bool:
    app = str(props.get("application.name") or "").strip().lower()
    binary = str(props.get("application.process.binary") or "").strip().lower()
    media = str(props.get("media.name") or "").strip().lower()
    return (binary == "firefox" or app == "firefox") and "chatgpt" in media


def _matches(items: Iterable[dict[str, Any]], *, direction: str) -> list[Match]:
    out: list[Match] = []
    for item in items:
        if not isinstance(item, dict):
            continue
        props = item.get("properties")
        if not isinstance(props, dict) or not _is_chatgpt_firefox(props):
            continue
        corked = _bool_corked(item.get("corked"))
        if corked:
            continue
        try:
            index = int(item.get("index") if item.get("index") is not None else -1)
        except Exception:
            index = -1
        out.append(Match(direction=direction,index=index,application_name=str(props.get("application.name") or ""),process_binary=str(props.get("application.process.binary") or ""),media_name=str(props.get("media.name") or ""),corked=False))
    return out


def classify(source_outputs: Any, sink_inputs: Any, *, playback_flow: Optional[dict[int, Optional[bool]]] = None, monotonic: Callable[[], float] = time.monotonic, wall: Callable[[], float] = time.time) -> PresenceSnapshot:
    if not isinstance(source_outputs, list) or not isinstance(sink_inputs, list):
        return PresenceSnapshot(STATE_UNKNOWN, monotonic(), wall(), "invalid_pactl_json_shape", ())
    captures = _matches(source_outputs, direction="capture")
    playbacks = _matches(sink_inputs, direction="playback")
    matches = tuple(captures + playbacks)
    if captures:
        return PresenceSnapshot(STATE_ACTIVE, monotonic(), wall(), "live_firefox_chatgpt_audio:capture", matches)
    if not playbacks:
        return PresenceSnapshot(STATE_INACTIVE, monotonic(), wall(), "no_uncorked_firefox_chatgpt_audio", ())
    if playback_flow is None:
        return PresenceSnapshot(STATE_UNKNOWN, monotonic(), wall(), "uncorked_playback_requires_pcm_flow_probe", matches)
    unknown = False
    for match in playbacks:
        flow = playback_flow.get(match.index)
        if flow is True:
            return PresenceSnapshot(STATE_ACTIVE, monotonic(), wall(), "live_firefox_chatgpt_audio:playback_pcm_flow", matches)
        if flow is not False:
            unknown = True
    if unknown:
        return PresenceSnapshot(STATE_UNKNOWN, monotonic(), wall(), "playback_pcm_flow_unknown", matches)
    return PresenceSnapshot(STATE_INACTIVE, monotonic(), wall(), "uncorked_playback_idle_no_pcm_flow", matches)


def _pactl_json(kind: str, *, timeout_s: float) -> list[dict[str, Any]]:
    proc = subprocess.run(["pactl", "-f", "json", "list", kind], text=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=max(0.1, float(timeout_s)), check=False)
    if proc.returncode != 0:
        raise RuntimeError(f"pactl {kind} rc={proc.returncode}: {proc.stderr[-300:]}")
    value = json.loads(proc.stdout or "[]")
    if not isinstance(value, list):
        raise ValueError(f"pactl {kind} returned non-list JSON")
    return value


def playback_pcm_flow(index: int, *, timeout_s: float = DEFAULT_PLAYBACK_PROBE_S) -> Optional[bool]:
    idx = int(index)
    if idx < 0:
        return None
    timeout = max(0.02, min(float(timeout_s), 0.30))
    try:
        proc = subprocess.Popen(["parec", f"--monitor-stream={idx}", "--raw", "--format=s16le", "--rate=8000", "--channels=1"], stdout=subprocess.PIPE, stderr=subprocess.PIPE, bufsize=0)
    except Exception:
        return None
    result: Optional[bool] = None
    try:
        stdout = proc.stdout
        if stdout is None:
            return None
        deadline = time.monotonic() + timeout
        while time.monotonic() < deadline:
            rc = proc.poll()
            if rc is not None:
                return False if rc == 0 else None
            remaining = max(0.0, deadline - time.monotonic())
            try:
                ready, _, _ = select.select([stdout], [], [], min(0.03, remaining))
            except Exception:
                return None
            if not ready:
                continue
            try:
                data = os.read(stdout.fileno(), 2)
            except Exception:
                return None
            if data:
                result = True
                break
            if proc.poll() is not None:
                result = False if proc.returncode == 0 else None
                break
        if result is None and proc.poll() is None:
            result = False
        return result
    finally:
        try:
            proc.terminate(); proc.wait(timeout=0.20)
        except Exception:
            try:
                proc.kill()
            except Exception:
                pass


def read_snapshot(*, timeout_s: float = 0.40, playback_probe_timeout_s: float = DEFAULT_PLAYBACK_PROBE_S) -> PresenceSnapshot:
    try:
        sources = _pactl_json("source-outputs", timeout_s=timeout_s)
        sinks = _pactl_json("sink-inputs", timeout_s=timeout_s)
        captures = _matches(sources, direction="capture")
        playbacks = _matches(sinks, direction="playback")
        if captures or not playbacks:
            return classify(sources, sinks, playback_flow={})
        flow: dict[int, Optional[bool]] = {}
        for match in playbacks[:MAX_PLAYBACK_PROBES]:
            flow[match.index] = playback_pcm_flow(match.index, timeout_s=playback_probe_timeout_s)
        return classify(sources, sinks, playback_flow=flow)
    except Exception as exc:
        return PresenceSnapshot(STATE_UNKNOWN, time.monotonic(), time.time(), f"sensor_error:{type(exc).__name__}:{str(exc)[:180]}", ())


class OmniPresenceMonitor:
    def __init__(self, *, stale_after_s: float = 2.0, watchdog_s: float = 0.75, snapshotter: Callable[[], PresenceSnapshot] = read_snapshot, popen: Callable[..., subprocess.Popen] = subprocess.Popen) -> None:
        self.stale_after_s = max(0.25, float(stale_after_s)); self.watchdog_s = max(0.10, min(float(watchdog_s), self.stale_after_s)); self._snapshotter = snapshotter; self._popen = popen; self._lock = threading.Lock(); self._snapshot = PresenceSnapshot(STATE_UNKNOWN, 0.0, 0.0, "not_started", ()); self._stop = threading.Event(); self._thread: Optional[threading.Thread] = None; self._subscriber: Optional[subprocess.Popen] = None
    def snapshot(self) -> PresenceSnapshot:
        with self._lock: return self._snapshot
    def _set(self, value: PresenceSnapshot) -> None:
        with self._lock: self._snapshot = value
    def refresh(self) -> PresenceSnapshot:
        try:
            value = self._snapshotter()
            if not isinstance(value, PresenceSnapshot): raise TypeError("snapshotter returned wrong type")
        except Exception as exc:
            value = PresenceSnapshot(STATE_UNKNOWN, time.monotonic(), time.time(), f"snapshotter_error:{type(exc).__name__}:{str(exc)[:180]}", ())
        self._set(value); return value
    def local_audio_admitted(self) -> bool:
        value = self.snapshot(); age = time.monotonic() - float(value.observed_mono or 0.0); return value.state == STATE_INACTIVE and 0.0 <= age <= self.stale_after_s
    def start(self) -> PresenceSnapshot:
        if self._thread is not None and self._thread.is_alive(): return self.snapshot()
        self._stop.clear(); first = self.refresh(); self._thread = threading.Thread(target=self._run, name="omega777-omni-presence", daemon=True); self._thread.start(); return first
    def _open_subscriber(self) -> subprocess.Popen:
        return self._popen(["pactl", "subscribe"], text=True, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, bufsize=1)
    def _close_subscriber(self) -> None:
        proc = self._subscriber; self._subscriber = None
        if proc is None: return
        try:
            proc.terminate(); proc.wait(timeout=0.4)
        except Exception:
            try: proc.kill()
            except Exception: pass
    def _run(self) -> None:
        last_refresh = time.monotonic()
        try:
            while not self._stop.is_set():
                if self._subscriber is None or self._subscriber.poll() is not None:
                    self._close_subscriber()
                    try: self._subscriber = self._open_subscriber()
                    except Exception as exc:
                        self._set(PresenceSnapshot(STATE_UNKNOWN,time.monotonic(),time.time(),f"subscribe_error:{type(exc).__name__}:{str(exc)[:180]}",())); self._stop.wait(min(0.25,self.watchdog_s)); continue
                proc = self._subscriber; stdout = proc.stdout if proc is not None else None; event_seen = False
                if stdout is not None:
                    try:
                        ready,_,_ = select.select([stdout],[],[],min(0.10,self.watchdog_s))
                        if ready:
                            line = stdout.readline().strip().lower(); event_seen = any(name in line for name in RELEVANT_PULSE_OBJECTS)
                    except Exception: self._close_subscriber()
                now = time.monotonic()
                if event_seen or now-last_refresh >= self.watchdog_s: self.refresh(); last_refresh = now
        finally: self._close_subscriber()
    def close(self) -> None:
        self._stop.set(); self._close_subscriber(); thread=self._thread
        if thread is not None: thread.join(timeout=1.0)
        self._thread=None; self._set(PresenceSnapshot(STATE_UNKNOWN,time.monotonic(),time.time(),"closed",()))
    def __enter__(self) -> "OmniPresenceMonitor": self.start(); return self
    def __exit__(self, exc_type, exc, tb) -> None: self.close()

__all__ = ["SCHEMA","STATE_ACTIVE","STATE_INACTIVE","STATE_UNKNOWN","Match","PresenceSnapshot","classify","playback_pcm_flow","read_snapshot","OmniPresenceMonitor"]
